L_values = [1, 2, 3]
counts = {}

# Formula: C(L, N) = 3 * (N - L + 1) * (N - L)
for L in L_values:
    if N >= L:
        count = 3 * (N - L + 1) * (N - L)
        counts[L] = count
    else:
        counts[L] = 0

print(f"Counts for L=1, 2, 3: {counts}")

